#include <stdio.h>
struct Node {
    int value;
    struct Node* next;
};
void func(struct Node* node) {
    while (node != NULL && node->next != NULL) {
        int t = node->value;
        node->value = node->next->value;
        node->next->value = t;
        node = node->next->next;
    }
}
int main() {
